// Ported from the Node app's Sequelize model TransportRoute (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class TransportRouteConfiguration : IEntityTypeConfiguration<TransportRoute>
{
    public void Configure(EntityTypeBuilder<TransportRoute> builder)
    {
        builder.ToTable("transport_routes");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(100)").HasMaxLength(100).IsRequired();
        builder.Property(e => e.VehicleId).HasColumnName("vehicle_id");
        builder.Property(e => e.MonthlyFee).HasColumnName("monthly_fee").HasColumnType("decimal(10,2)").HasDefaultValueSql("0");
        builder.HasIndex(e => e.Name).IsUnique();
        builder.HasOne(e => e.Vehicle).WithMany(p => p.TransportRoutes).HasForeignKey(e => e.VehicleId).OnDelete(DeleteBehavior.NoAction);
    }
}
